CREATE TABLE job_position (
	name VARCHAR(200) NOT NULL, 
	department VARCHAR(120) NOT NULL, 
	description VARCHAR(4000) NOT NULL, 
	requirements VARCHAR(4000) NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	employment_type VARCHAR(20) NOT NULL, 
	location VARCHAR(200) NOT NULL, 
	salary_min NUMERIC(12, 2) NOT NULL, 
	salary_max NUMERIC(12, 2) NOT NULL, 
	currency VARCHAR(3) NOT NULL, 
	owner_user_id UUID, 
	id UUID NOT NULL, 
	org_id UUID NOT NULL, 
	ext JSONB DEFAULT '{}'::jsonb NOT NULL, 
	custom JSONB DEFAULT '{}'::jsonb NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	deleted_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id)
);

CREATE INDEX ix_job_position_org_id ON job_position (org_id);

ALTER TABLE job_position ENABLE ROW LEVEL SECURITY;
ALTER TABLE job_position FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON job_position
